"""Read-only local release audit; no model imports, data download, or subprocesses."""
import argparse
import ast
import gzip
import hashlib
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PROHIBITED_SUFFIXES = {".jpg", ".jpeg", ".png", ".bmp", ".mp4", ".avi", ".mov",
                       ".pt", ".pth", ".onnx", ".engine", ".whl", ".zip", ".tar"}
WINDOWS_ABSOLUTE = re.compile(r"(?<![A-Za-z0-9])[A-Za-z]:[\\/]")
HOME_ABSOLUTE = re.compile(r"/(?:Users|home)/[^/\s\"']+/")
EMAIL = re.compile(r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b")

def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def child_path(value):
    p = ROOT / value
    if p.is_symlink() or not p.resolve().is_relative_to(ROOT):
        raise ValueError("Manifest path escapes the repository")
    return p

def audit(forbid_tokens=()):
    findings, emails, hashes = [], [], []
    reviewed_findings = []
    py_count = gzip_count = 0
    for path in sorted(ROOT.rglob("*")):
        rel = path.relative_to(ROOT).as_posix()
        if path.is_symlink():
            findings.append({"path": rel, "kind": "symlink"})
            continue
        if not path.is_file():
            continue
        if ".git" in path.parts or "__pycache__" in path.parts:
            findings.append({"path": rel, "kind": "generated_or_git_metadata"})
        raw = path.read_bytes()
        hashes.append({"path": rel, "bytes": len(raw), "sha256": digest(raw)})
        if path.suffix.lower() in PROHIBITED_SUFFIXES or path.name == "gt.txt":
            findings.append({"path": rel, "kind": "excluded_data_or_weight_file"})
        try:
            content = gzip.decompress(raw) if path.suffix == ".gz" else raw
            gzip_count += int(path.suffix == ".gz")
            text = content.decode("utf-8-sig")
        except (UnicodeError, OSError, EOFError):
            findings.append({"path": rel, "kind": "uninspected_non_text"})
            continue
        for number, line in enumerate(text.splitlines(), 1):
            if WINDOWS_ABSOLUTE.search(line) or HOME_ABSOLUTE.search(line):
                findings.append({"path": rel, "line": number, "kind": "absolute_machine_path"})
            # Match a whole identity token, not a digit substring in a coordinate/hash.
            if any(t and re.search(r"(?<![A-Za-z0-9_.])" + re.escape(t) +
                                   r"(?![A-Za-z0-9_.])", line, re.IGNORECASE)
                   for t in forbid_tokens):
                findings.append({"path": rel, "line": number, "kind": "local_identity_token"})
            if EMAIL.search(line):
                emails.append({"path": rel, "line": number, "kind": "email_requires_attribution_review"})
        if path.suffix == ".py":
            py_count += 1
            try:
                ast.parse(text, filename=rel)
            except SyntaxError as error:
                findings.append({"path": rel, "line": error.lineno, "kind": "python_syntax"})
    exceptions_path = ROOT / "metadata/privacy_reviewed_exceptions.json"
    if exceptions_path.exists():
        review = json.loads(exceptions_path.read_text(encoding="utf-8"))
        for exc in review["reviewed"]:
            path = child_path(exc["path"])

"""Explicit JSON adapters for unchanged analytical primitives; no data discovery."""
import argparse
from dataclasses import asdict
from fractions import Fraction
from pathlib import Path
from src.detect.io import development, fragment_namespace, frozen_module, load_json, new_output, require, write_json

FILES = {"e1": "r15e28_e1_core78a_v2.py", "e2": "r15e28_e2_masks.py",
         "headgate": "r15e27_headgate_inference.py", "d1": "r15e29_gap_core81.py",
         "gatelink": "r15e32_gatelink_oracle.py"}


def module(key):
    return frozen_module("src/analysis/frozen/" + FILES[key], "_portable_" + key)


def analyze(action, doc):
    development(doc["sequence"])
    if action == "reid-decision":
        ns = fragment_namespace("r15_reid93_analysis.py", {"Fraction": Fraction})
        return ns["decision"](doc["report"])
    if action == "reid-support":
        ns = fragment_namespace("r15_reid93_analysis.py", {"Fraction": Fraction})
        return dict(categories=[ns["sidecat"](support) for support in doc["supports"]],
                    interpretation="descriptive support categories; no identity reassignment or causal claim")
    if action == "e2-mask":
        m = module("e2")
        rows = [m.Observation(**row) for row in doc["observations"]]
        require(all(row.sequence_id == doc["sequence"] for row in rows), "Observation sequence differs")
        return asdict(m.make_mask(rows, retention=doc["retention"], seed=doc["seed"],
                                  mode=doc["mode"], fps_by_sequence={doc["sequence"]: doc["fps"]}))
    if action == "d1-gaps":
        timelines = {int(k): v for k, v in doc["timelines"].items()}
        return dict(gaps=module("d1").gaps(timelines, fps=doc["fps"]), descriptive_only=True)
    if action == "headgate-project":
        projection = module("headgate").HeadProjection(mode="mot", anchor="head_box_bottom_center",
            size=doc["native_size"], calibration=doc["calibration"])
        return dict(points=[projection.point(d) for d in doc["detections"]], metadata=projection.metadata())
    if action == "gatelink":
        m = module("gatelink")
        require(doc["max_gap_frames"] in (50, 125), "Frozen GateLink gap must be 50 or 125 frames")
        if doc["mode"] == "bridge":
            rows, added = m.bridge_same_id(doc["rows"], doc["max_gap_frames"])
            return dict(rows=rows, added=added, oracle=True)
        require(doc["mode"] == "link", "GateLink mode must be bridge or link")
        ids = {(r["source_frame"], r["track_id"]): r["gt_id"] for r in doc["valid_identities"]}
        rows, links, added = m.oracle_link(doc["rows"], ids, doc["max_gap_frames"])
        return dict(rows=rows, links=links, added=added, oracle=True)
    if action == "e1-pools":
        raw, outputs, mapping, detections = module("e1").pools(doc["frame"], doc["system"])
        return dict(admitted=raw, outputs=outputs, raw_to_output=mapping, detections=detections)
    if action == "e1-attribute":
        args = dict(doc["arguments"])
        for key in ("support", "gtframes", "outputobs"):
            args[key] = {int(k): v for k, v in args[key].items()}
        args["fragment_lookup"] = {(r["source_frame"], r["track_id"]): tuple(r["fragment"])
                                   for r in args["fragment_lookup"]}
        category, subtype, details = module("e1").attribute(**args)
        return dict(category=category, subtype=subtype, details=details, causal_claim=False)
    if action == "m4-stitch":
        m = frozen_module("src/track/frozen/r15e26_stitch_v2.py", "_portable_m4")
        return m.stitch_frame_rows(doc["frames"], namespace=doc["namespace"], fps=doc["fps"],
                                  gates=doc["gates"], g1=doc["g1"], clarification=doc["policy"])
    raise ValueError("Unsupported analysis action")


def main(argv=None):
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("action", choices=("e2-mask", "d1-gaps", "headgate-project", "gatelink",
                                      "e1-pools", "e1-attribute", "m4-stitch", "reid-decision", "reid-support"))

def decision(report):
    agg=report['main']['aggregate'];seqs=report['main']['by_sequence']
    if any(u['final_events']==0 for u in [agg,*seqs.values()]):
        return dict(decision='TECHNICAL_STOP / INCONCLUSIVE',reason='identity precision undefined (N=0)',state='PENDING_CLAUDE_RECOMPUTE')
    def p(u):return Fraction(u['correct'],u['final_events'])
    safe={
        'all_high_ge_206':agg['bins']['high']['numerator']>=206,
        'all_precision_floor':p(agg)>=Fraction(14283,15850),
        '01_high_ge_12':seqs['MOT20-01']['bins']['high']['numerator']>=12,
        '02_high_ge_194':seqs['MOT20-02']['bins']['high']['numerator']>=194,
        '01_precision_floor':p(seqs['MOT20-01'])>=Fraction(509,550),
        '02_precision_floor':p(seqs['MOT20-02'])>=Fraction(26021,28950),
    }
    low={
        'all_low_ge_99':agg['bins']['low']['numerator']>=99,
        '01_low_ge_16':seqs['MOT20-01']['bins']['low']['numerator']>=16,
        '02_low_ge_70':seqs['MOT20-02']['bins']['low']['numerator']>=70,
    }
    delta=agg['bins']['low']['numerator']-84
    if not all(safe.values()):verdict='NOT_ADOPT / BASELINE_WITH_REGRESSION'
    elif delta<=-6:verdict='STOP_REPAIR_DIRECTION_FOR_THIS_CONFIGURATION'
    elif delta<=5:verdict='BASELINE_ONLY'
    elif delta<=14:verdict='DESCRIPTIVE_ONLY'
    elif not all(low.values()):verdict='DESCRIPTIVE_ONLY / SEQUENCE_DEPENDENT'
    else:verdict='CONTINUE_CANDIDATE'
    return dict(decision=verdict,state='PENDING_CLAUDE_RECOMPUTE',safety_checks=safe,low_checks=low,
        delta_low_correct=delta,exact_precision={k:fraction_value(u['correct'],u['final_events']) for k,u in [('ALL',agg),*seqs.items()]},
        thresholds=dict(all_precision='14283/15850',seq01_precision='509/550',seq02_precision='26021/28950'),
        rules_sha256=RULES_SHA,not_significance_test=True)

